solutionCode:
export function calcularTotal(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.reduce((total, n) => total + n, 0);
}

export function encontrarMaior(lista) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.reduce((maior, n) => (n > maior ? n : maior), lista[0]);
}
